export const getListInquiriesUrl = (params?: ListInquiriesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/inquiries?${stringifiedParams}` : `/api/inquiries`
}

/**
 * @summary List all inquiries (admin)
 */
export const listInquiries = async (params?: ListInquiriesParams, options?: RequestInit): Promise<Inquiry[]> => {

  return customFetch<Inquiry[]>(getListInquiriesUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getListInquiriesQueryKey = (params?: ListInquiriesParams,) => {
    return [
    `/api/inquiries`, ...(params ? [params] : [])
    ] as const;
    }


export const getListInquiriesQueryOptions = <TData = Awaited<ReturnType<typeof listInquiries>>, TError = ErrorType<unknown>>(params?: ListInquiriesParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listInquiries>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getListInquiriesQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof listInquiries>>> = ({ signal }) => listInquiries(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listInquiries>>, TError, TData> & { queryKey: QueryKey }
}

export type ListInquiriesQueryResult = NonNullable<Awaited<ReturnType<typeof listInquiries>>>
export type ListInquiriesQueryError = ErrorType<unknown>


